const MAX_LEN:usize=256;
fn reverse_bytes(a:[]u8,from:usize,to:usize)void{var left=from;var right=to;while(left<right){const t=a[left];a[left]=a[right];a[right]=t;left+=1;right-=1;}}
export fn char_array_left_rotation(input:?[*]const i64,length:usize,output:?[*]u8,capacity:usize)i64{if(input==null or length<2 or length>MAX_LEN+3)return -1;const v=input.?[0..length];if(v[0]<0 or v[0]>256)return -1;const n:usize=@intCast(v[0]);if(v[1]<0 or v[1]>@as(i64,@intCast(n)) or length!=n+2)return -1;for(v[2..])|x|{if(x<0 or x>127)return -1;}if(output==null or capacity<n)return -2;var a=[_]u8{0}**MAX_LEN;for(0..n)|i|a[i]=@intCast(v[i+2]);const k:usize=@intCast(v[1]);if(k>0)reverse_bytes(a[0..n],0,k-1);if(k<n)reverse_bytes(a[0..n],k,n-1);if(n>0)reverse_bytes(a[0..n],0,n-1);const out=output.?[0..capacity];@memcpy(out[0..n],a[0..n]);return @intCast(n);}
